"use client";
import VideoPlayer from '../../components/VideoPlayer/page.jsx';
import { useState, useEffect } from "react";
import axios from "axios";



export default function Page() {
  const { url, tracks } = useVideoSource(" https://yumaapi.vercel.app/watch?episodeId=dragon-ball-509$episode$10218&type=sub&server=megacloud");

  if (!url) return <p>Carregando vídeo...</p>;

  return <VideoPlayer src={url} subtitles={tracks} />;
}